-- public.sacrifice_setting(p_world uuid, p_uid uuid, p_target jsonb, OUT o_why text, OUT o_item item)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.sacrifice_setting(p_world uuid, p_uid uuid, p_target jsonb, OUT o_why text, OUT o_item item)
 RETURNS record
 LANGUAGE plpgsql
 STABLE
AS $function$
declare v_pc placed;
begin
  select * into v_pc from placed pl where pl.world_id = p_world and pl.id = (p_target->>'id')::bigint;
  if not found or not is_altar(v_pc) then o_why := 'Not an altar.'; return; end if;
  if not near_piece(p_world, p_uid, v_pc, 2.4) then o_why := 'Stand at the altar.'; return; end if;
  select * into o_item from item i where i.world_id = p_world and i.id = target_item(p_target)
    and i.holder = 'player' and i.holder_uid = p_uid;
  if o_item.id is null then o_why := 'Choose a rare, supreme or fantastic item.'; return; end if;
  if o_item.def = 'soul' then o_why := 'Souls cannot be sacrificed: absorb it into an item.'; return; end if;
  if o_item.rare is null then o_why := 'Only rare, supreme or fantastic items.'; return; end if;
  if o_item.locked then o_why := 'Set aside: return it to the pack first.'; return; end if;
  if exists (select 1 from player p cross join lateral jsonb_each_text(p.equipped) e
              where p.world_id = p_world and p.uid = p_uid and e.value = o_item.id::text) then
    o_why := 'Take it off first.'; return;
  end if;
  if exists (select 1 from item c where c.world_id = p_world and c.inside = o_item.id) then
    o_why := 'Empty it first.'; return;
  end if;
  if o_item.creature is not null then o_why := 'Release the wildermon first.'; return; end if;
end $function$
